//
// C-10 (NFR-U3-20; TS-U3-08): the agent-side contract types, generated by the
// vendored generator (contract/scripts/generate-types.ts, soorma-core's), from
// the vendored contract: the components, S3 (data-gateway) and S4
// (event-ingest). No S1 or S2 type is generated (NEV-01; I6).
//   node typescript/scripts/generate.ts <out-dir>
import { mkdirSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { generate } from '../../contract/scripts/generate-types.ts';

const contract = resolve(import.meta.dirname, '..', '..', 'contract');
export const AGENT_SIDE = [
  ['conventions/components.openapi.yaml', 'components.ts'],
  ['data-gateway.openapi.yaml', 'data-gateway.ts'],
  ['event-ingest.openapi.yaml', 'event-ingest.ts'],
] as const;

if (import.meta.main) {
  const out = resolve(process.argv[2] ?? join(import.meta.dirname, '..', 'src', 'generated'));
  mkdirSync(out, { recursive: true });
  for (const [doc, file] of AGENT_SIDE) {
    writeFileSync(join(out, file), await generate(join(contract, doc), `contract/${doc}`));
  }
}
